\documentclass{article}
\usepackage{pgfplots}
\usepackage{tikz}
\usepackage{tkz-euclide}
\usetikzlibrary{arrows} %% Can be useful, not essential
\usetikzlibrary{intersections} %% Can be useful, not essential
\usepgfplotslibrary{fillbetween} %% Can be useful, not essential

\begin{document}

\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\pagestyle{empty} %% IMPORTANT
\begin{tikzpicture}

\begin{axis}[
legend pos=outer north east,
tick label style={font=\footnotesize},
label style={font=\small},
legend style={font=\footnotesize},
tick style={draw=none},
axis line style = thick,
axis y line = center,
axis x line = middle,
axis equal,
%grid = both,
xmin = -7,
xmax = 7,
ymin = -7,
ymax = 7,
xtick = {-50,50},
ytick = {-50,50},
xlabel = {$x_1$},
ylabel = {$x_2$},
xlabel style={right},
ylabel style={above},
]

% ax_1^2 + bx_1x_2 + cx_2^2 = d
% x_2 = (1/(2*c))*(\pm sqrt(4*c*d + (b*b - 4*a*c)*x*x) - b*x)
\def\a{2}
\def\b{-6}
\def\c{2}
\def\d{7}

% Eigenvalues
\def\lamo{0.75}
\def\lamt{-5}

\def\rangex{sqrt((4*\c*\d)/(4*\a*\c - \b*\b))}
\def\mycolor{deepskyblue}

% Hyperbolic Curve
%% If domain is x\in R
\plot[very thick, domain=-10:10, samples=200, color=\mycolor] ({x},{(1/(2*\c))*(sqrt(4*\c*\d + (\b*\b - 4*\a*\c)*x*x) - \b*x)});
\plot[very thick, domain=-10:10, samples=200, color=\mycolor] ({x},{(1/(2*\c))*(-1*sqrt(4*\c*\d + (\b*\b - 4*\a*\c)*x*x) - \b*x)});
%% If domain is x\in (-\infty, -\rangex) U (\rangex, \infty)
%\plot[very thick, domain={\rangex}:10, samples=200, color=\mycolor] ({x},{(1/(2*\c))*(sqrt(4*\c*\d + (\b*\b - 4*\a*\c)*x*x) - \b*x)});
%\plot[very thick, domain=-10:{-1*\rangex}, samples=200, color=\mycolor] ({x},{(1/(2*\c))*(sqrt(4*\c*\d + (\b*\b - 4*\a*\c)*x*x) - \b*x)});
%\plot[very thick, domain={\rangex}:10, samples=200, color=\mycolor] ({x},{(1/(2*\c))*(-1*sqrt(4*\c*\d + (\b*\b - 4*\a*\c)*x*x) - \b*x)});
%\plot[very thick, domain=-10:{-1*\rangex}, samples=200, color=\mycolor] ({x},{(1/(2*\c))*(-1*sqrt(4*\c*\d + (\b*\b - 4*\a*\c)*x*x) - \b*x)});

% Principal axes
\plot[domain=-10:10, samples=200, color=rustred, dashed, thick] ({x},{(\b*x/(2*\lamo - 2*\c))});
\plot[domain=-10:10, samples=200, color=rustred, dashed, thick] ({x},{(\b*x/(2*\lamt - 2*\c))});

\end{axis}
\end{tikzpicture}
\end{document}

